namespace NightLens {
class HorizonCanvas:Control {
    public HorizonProfile Profile;public HorizonPoint Selected;public event Action Changed;bool dragging;Rectangle plot;
    public HorizonCanvas(HorizonProfile profile){Profile=profile;DoubleBuffered=true;Cursor=Cursors.Cross;Font=new Font("Segoe UI",9);AccessibleName="Editable horizon skyline";}
    double GraphFloor {get{return Profile.Points.Any(p=>p.Altitude<0)?-30:0;}}
    PointF XY(HorizonPoint p){return new PointF(plot.Left+(float)(p.Azimuth/360*plot.Width),plot.Bottom-(float)((p.Altitude-GraphFloor)/(90-GraphFloor)*plot.Height));}
    public void Put(double az,double alt){az=(az%360+360)%360;var existing=Profile.Points.FirstOrDefault(p=>Math.Abs(p.Azimuth-az)<.05&&p!=Selected);if(Selected==null){Selected=existing??new HorizonPoint();if(existing==null)Profile.Points.Add(Selected);}else if(existing!=null){Profile.Points.Remove(existing);}Selected.Azimuth=az;Selected.Altitude=alt;Profile.Points.Sort((a,b)=>a.Azimuth.CompareTo(b.Azimuth));Invalidate();Changed?.Invoke();}
    public void Remove(){if(Selected!=null)Profile.Points.Remove(Selected);Selected=null;Invalidate();Changed?.Invoke();}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left||!plot.Contains(e.Location))return;Selected=Profile.Points.OrderBy(p=>Math.Pow(XY(p).X-e.X,2)+Math.Pow(XY(p).Y-e.Y,2)).FirstOrDefault();if(Selected==null||Math.Sqrt(Math.Pow(XY(Selected).X-e.X,2)+Math.Pow(XY(Selected).Y-e.Y,2))>12)Selected=null;dragging=true;Capture=true;MovePoint(e.Location);}
    protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(dragging)MovePoint(e.Location);}
    void MovePoint(Point point){double az=Math.Max(0,Math.Min(359.99,(point.X-plot.Left)*360.0/Math.Max(1,plot.Width))),alt=90-(Math.Max(plot.Top,Math.Min(plot.Bottom,point.Y))-plot.Top)*(90-GraphFloor)/Math.Max(1,plot.Height);Put(Math.Round(az,2),Math.Round(alt,2));}
    protected override void OnMouseUp(MouseEventArgs e){dragging=false;Capture=false;base.OnMouseUp(e);}
    protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Style.Card);g.SmoothingMode=SmoothingMode.AntiAlias;plot=new Rectangle(44,15,Math.Max(10,Width-62),Math.Max(10,Height-49));using(var line=new Pen(Color.FromArgb(65,Style.Muted)))using(var text=new SolidBrush(Style.Muted)){foreach(int h in new[]{-30,0,30,60,90})if(h>=GraphFloor){float y=XY(new HorizonPoint{Altitude=h}).Y;g.DrawLine(line,plot.Left,y,plot.Right,y);g.DrawString(h+"°",Font,text,3,y-7);}string[] compass={"N","NE","E","SE","S","SW","W","NW","N"};for(int i=0;i<=8;i++){float x=plot.Left+plot.Width*i/8f;g.DrawLine(line,x,plot.Top,x,plot.Bottom);g.DrawString(compass[i],Font,text,x-7,plot.Bottom+8);}}
        var display=Profile.Copy();display.Enabled=true;display.Normalize();var points=Enumerable.Range(0,361).Select(az=>XY(new HorizonPoint{Azimuth=az,Altitude=display.Height(az)})).ToList();using(var area=new GraphicsPath()){area.AddPolygon(new[]{new PointF(plot.Left,plot.Bottom)}.Concat(points).Concat(new[]{new PointF(plot.Right,plot.Bottom)}).ToArray());using(var fill=new SolidBrush(Color.FromArgb(35,Style.Text)))g.FillPath(fill,area);}using(var line=new Pen(Profile.Enabled?Style.Text:Style.Muted,2))g.DrawLines(line,points.ToArray());using(var minimum=new Pen(Style.Muted,1){DashStyle=DashStyle.Dash}){float y=XY(new HorizonPoint{Altitude=Profile.MinimumAltitude}).Y;g.DrawLine(minimum,plot.Left,y,plot.Right,y);}foreach(var p in Profile.Points){var xy=XY(p);using(var brush=new SolidBrush(p==Selected?Style.Text:Style.Muted))g.FillEllipse(brush,xy.X-4,xy.Y-4,8,8);}
    }
}
class HorizonForm:Form {
    public HorizonProfile Result;HorizonCanvas chart;NumericUpDown az,alt,minimum;CheckBox enabled;Label note;bool filling;double latitude,longitude;
    static NumericUpDown Number(decimal min,decimal max,decimal value,int decimals=1){return new NumericUpDown{Minimum=min,Maximum=max,Value=value,DecimalPlaces=decimals,Increment=1,Dock=DockStyle.Fill,ThousandsSeparator=false};}
    public HorizonForm(HorizonProfile input,double lat,double lon){latitude=lat;longitude=lon;Result=(input??new HorizonProfile()).Copy();Result.Normalize();Style.Form(this);Text="Horizon mask";Style.FitScreen(this,1040,620);var root=Style.Grid(1,35,48,35,-100,53,25,40);root.Padding=new Padding(12);Controls.Add(root);root.Controls.Add(Style.Label("Your local skyline",20,true),0,0);
        var top=Style.Grid(4,-100);enabled=new CheckBox{Text="Use horizon mask",Checked=Result.Enabled,Dock=DockStyle.Fill};minimum=Number(0,89,(decimal)Result.MinimumAltitude);top.Controls.Add(enabled,0,0);top.Controls.Add(Style.Field("Minimum target altitude (°)",minimum),1,0);top.Controls.Add(Style.Button("Import .hrz…",(a,b)=>Import()),2,0);top.Controls.Add(Style.Button("Clear points",(a,b)=>{chart.Profile.Points.Clear();chart.Selected=null;chart.Invalidate();Fill();}),3,0);root.Controls.Add(top,0,1);
        root.Controls.Add(Style.Label("Click to add a point; drag it to match trees or buildings. Azimuth: N 0° · E 90° · S 180° · W 270°. Dashed line: minimum altitude.",10),0,2);chart=new HorizonCanvas(Result){Dock=DockStyle.Fill};chart.Changed+=Fill;root.Controls.Add(chart,0,3);
        var point=Style.Grid(4,-100);az=Number(0,360,0,2);alt=Number(-30,90,0,2);point.Controls.Add(Style.Field("Point azimuth (°)",az),0,0);point.Controls.Add(Style.Field("Point altitude (°)",alt),1,0);point.Controls.Add(Style.Button("Add / update point",(a,b)=>chart.Put((double)az.Value,(double)alt.Value)),2,0);point.Controls.Add(Style.Button("Delete selected",(a,b)=>chart.Remove()),3,0);root.Controls.Add(point,0,4);note=Style.Label("",9);root.Controls.Add(note,0,5);var buttons=Style.Grid(2,-100);buttons.Controls.Add(Style.Button("Cancel",(a,b)=>Close()),0,0);buttons.Controls.Add(Style.Button("Save horizon",(a,b)=>{try{Result=chart.Profile.Copy();Result.Enabled=enabled.Checked;Result.MinimumAltitude=(double)minimum.Value;Result.AnchorLat=latitude;Result.AnchorLon=longitude;Result.Normalize();DialogResult=DialogResult.OK;Close();}catch(Exception ex){note.Text=ex.Message;}}),1,0);root.Controls.Add(buttons,0,6);
        enabled.CheckedChanged+=(a,b)=>{chart.Profile.Enabled=enabled.Checked;chart.Invalidate();};minimum.ValueChanged+=(a,b)=>{chart.Profile.MinimumAltitude=(double)minimum.Value;chart.Invalidate();};az.ValueChanged+=(a,b)=>EditPoint();alt.ValueChanged+=(a,b)=>EditPoint();Fill();Style.Apply(this);
    }
    void EditPoint(){if(!filling&&chart.Selected!=null)chart.Put((double)az.Value,(double)alt.Value);}
    void Fill(){filling=true;try{if(chart.Selected!=null){az.Value=(decimal)chart.Selected.Azimuth;alt.Value=(decimal)chart.Selected.Altitude;}note.Text=chart.Profile.Points.Count+" skyline points · targets must clear both the skyline and minimum altitude";}finally{filling=false;}}
    void Import(){using(var picker=new OpenFileDialog{Filter="Horizon data (*.hrz;*.txt;*.csv)|*.hrz;*.txt;*.csv|All files (*.*)|*.*",Title="Import Stellarium horizon points"}){if(picker.ShowDialog(this)!=DialogResult.OK)return;using(var options=new HorizonImportForm()){if(options.ShowDialog(this)!=DialogResult.OK)return;try{if(new FileInfo(picker.FileName).Length>256*1024)throw new FormatException("Horizon files must be 256 KB or smaller.");var imported=HorizonProfile.Import(File.ReadAllText(picker.FileName),options.Mode,options.Rotation);imported.MinimumAltitude=(double)minimum.Value;imported.Enabled=enabled.Checked;chart.Profile=imported;chart.Selected=null;chart.Invalidate();Fill();}catch(Exception ex){note.Text="Import failed: "+ex.Message;}}}}
}
class HorizonImportForm:Form {
    public string Mode;public double Rotation;ComboBox formats;NumericUpDown rotation;
    public HorizonImportForm(){Style.Form(this);Text="Horizon import options";Style.FitScreen(this,700,260);var root=Style.Grid(1,45,53,53,40);root.Padding=new Padding(12);Controls.Add(root);root.Controls.Add(Style.Label("Standard .hrz files use north-to-east azimuth and altitude in degrees. For other Stellarium landscape modes, choose the units below.",10),0,0);formats=Style.Combo();formats.Items.AddRange(new object[]{"azDeg_altDeg","azDeg_zdDeg","azRad_altRad","azRad_zdRad","azGrad_altGrad","azGrad_zdGrad"});formats.SelectedIndex=0;root.Controls.Add(Style.Field("Stellarium list mode",formats),0,1);rotation=new NumericUpDown{Minimum=-360,Maximum=360,DecimalPlaces=3,Dock=DockStyle.Fill};root.Controls.Add(Style.Field("Azimuth rotation (degrees; usually 0)",rotation),0,2);root.Controls.Add(Style.Button("Import points",(a,b)=>{Mode=Convert.ToString(formats.SelectedItem);Rotation=(double)rotation.Value;DialogResult=DialogResult.OK;Close();}),0,3);Style.Apply(this);}
}
class SiteEditorForm:Form {
    public ObservingSite Result;TextBox name,lat,lon,sqm;ComboBox zone;CheckBox known,estimate;NumericUpDown bortle;Label note;HorizonProfile horizon;
    public SiteEditorForm(ObservingSite site){Result=Json.Read<ObservingSite>(Json.Write(site));horizon=Result.Horizon.Copy();Style.Form(this);Text="Observing site";Style.FitScreen(this,820,500);var root=Style.Grid(1,35,-100,26,40);root.Padding=new Padding(12);Controls.Add(root);root.Controls.Add(Style.Label("Save your observing site",19,true),0,0);var fields=Style.Grid(2,53,53,53,53,34,38);name=new TextBox{Text=Result.Name};var named=Style.Field("Site name",name);fields.Controls.Add(named,0,0);fields.SetColumnSpan(named,2);lat=new TextBox{Text=Net.Coord(Result.Lat)};lon=new TextBox{Text=Net.Coord(Result.Lon)};fields.Controls.Add(Style.Field("Latitude",lat),0,1);fields.Controls.Add(Style.Field("Longitude",lon),1,1);zone=Style.Combo();foreach(var z in TimeZoneInfo.GetSystemTimeZones())zone.Items.Add(z);zone.DisplayMember="DisplayName";zone.SelectedItem=zone.Items.Cast<TimeZoneInfo>().FirstOrDefault(z=>z.Id==Result.Zone);var zf=Style.Field("Time zone",zone);fields.Controls.Add(zf,0,2);fields.SetColumnSpan(zf,2);var b=Style.Grid(2,-100);known=new CheckBox{Text="Bortle set",Checked=Result.Sky!=null,Dock=DockStyle.Fill};bortle=new NumericUpDown{Minimum=1,Maximum=9,DecimalPlaces=1,Increment=.1m,Value=(decimal)(Result.Sky?.Bortle??5),Dock=DockStyle.Fill};b.Controls.Add(known,0,0);b.Controls.Add(bortle,1,0);fields.Controls.Add(Style.Field("Light pollution",b),0,3);sqm=new TextBox{Text=Result.Sky?.Sqm?.ToString("0.00",CultureInfo.InvariantCulture)??""};fields.Controls.Add(Style.Field("SQM (optional)",sqm),1,3);estimate=new CheckBox{Text="Bortle is an area estimate",Checked=Result.Sky?.AreaEstimate??false,Dock=DockStyle.Fill};fields.Controls.Add(estimate,0,4);fields.SetColumnSpan(estimate,2);var edit=Style.Button("Edit this site's horizon…",(a,e)=>{double la,lo;if(!Coordinates(out la,out lo)){note.Text="Enter valid coordinates before editing the horizon.";return;}var local=horizon.AnchorLat.HasValue&&SkySite.Distance(la,lo,horizon.AnchorLat.Value,horizon.AnchorLon??lo)>horizon.RadiusKm?new HorizonProfile{MinimumAltitude=horizon.MinimumAltitude}:horizon;using(var form=new HorizonForm(local,la,lo))if(form.ShowDialog(this)==DialogResult.OK)horizon=form.Result;});fields.Controls.Add(edit,0,5);fields.SetColumnSpan(edit,2);root.Controls.Add(fields,0,1);note=Style.Label("Saves coordinates, time zone, sky brightness and horizon together.",9);root.Controls.Add(note,0,2);var actions=Style.Grid(2,-100);actions.Controls.Add(Style.Button("Cancel",(a,b1)=>Close()),0,0);actions.Controls.Add(Style.Button("Save site",(a,b1)=>Save()),1,0);root.Controls.Add(actions,0,3);Style.Apply(this);}
    bool Coordinates(out double la,out double lo){la=lo=0;return double.TryParse(lat.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out la)&&double.TryParse(lon.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out lo)&&!double.IsNaN(la)&&!double.IsInfinity(la)&&Math.Abs(la)<=90&&!double.IsNaN(lo)&&!double.IsInfinity(lo)&&Math.Abs(lo)<=180;}
    void Save(){try{double la,lo;if(!Coordinates(out la,out lo))throw new FormatException("Enter valid latitude and longitude.");if(zone.SelectedItem==null)throw new FormatException("Choose a time zone.");double sky;double? sq=null;if(!string.IsNullOrWhiteSpace(sqm.Text)){if(!double.TryParse(sqm.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out sky)||double.IsNaN(sky)||sky<10||sky>25)throw new FormatException("SQM must be between 10 and 25.");sq=sky;}Result.Name=name.Text.Trim();Result.Lat=la;Result.Lon=lo;Result.Zone=((TimeZoneInfo)zone.SelectedItem).Id;Result.Horizon=horizon;Result.Sky=known.Checked?new SkySite{Lat=la,Lon=lo,Bortle=(double)bortle.Value,Sqm=sq,RadiusKm=1,AreaEstimate=estimate.Checked,Source="Saved observing site"}:null;SiteLibrary.Validate(Result);DialogResult=DialogResult.OK;Close();}catch(Exception ex){note.Text=ex.Message;}}
}
class SavedSitesForm:Form {
    public Settings Result;ListBox list;Label details;
    public SavedSitesForm(Settings input){Result=Json.Read<Settings>(Json.Write(input));SiteLibrary.Normalize(Result);Style.Form(this);Text="Saved observing sites";Style.FitScreen(this,920,470);var root=Style.Grid(1,35,34,-100,40,35,40);root.Padding=new Padding(12);Controls.Add(root);root.Controls.Add(Style.Label("Your observing sites",20,true),0,0);root.Controls.Add(Style.Label("Keep home, dark sites and travel locations together. Choosing a saved site uses its coordinates instead of Windows Location.",10),0,1);var content=Style.Grid(2,-100);content.ColumnStyles[0].Width=43;content.ColumnStyles[1].Width=57;list=new ListBox{Dock=DockStyle.Fill,IntegralHeight=false};list.SelectedIndexChanged+=(a,b)=>Details();details=Style.Label("",11);details.TextAlign=ContentAlignment.TopLeft;details.Padding=new Padding(12);content.Controls.Add(list,0,0);content.Controls.Add(details,1,0);root.Controls.Add(content,0,2);var buttons=Style.Grid(4,-100);buttons.Controls.Add(Style.Button("Save current site…",(a,b)=>Add()),0,0);buttons.Controls.Add(Style.Button("Edit selected…",(a,b)=>Edit()),1,0);buttons.Controls.Add(Style.Button("Remove selected",(a,b)=>Remove()),2,0);buttons.Controls.Add(Style.Button("Use selected site",(a,b)=>Use()),3,0);root.Controls.Add(buttons,0,3);root.Controls.Add(Style.Label("Changes take effect when you use a site or save and close. Cancel leaves your current setup unchanged.",9),0,4);var close=Style.Grid(2,-100);close.Controls.Add(Style.Button("Cancel",(a,b)=>Close()),0,0);close.Controls.Add(Style.Button("Save and close",(a,b)=>{DialogResult=DialogResult.OK;Close();}),1,0);root.Controls.Add(close,0,5);Reload(Result.ActiveSiteId);Style.Apply(this);}
    ObservingSite Selected {get{return list.SelectedItem as ObservingSite;}}
    void Reload(string id=null){list.Items.Clear();foreach(var site in Result.Sites)list.Items.Add(site);list.SelectedItem=Result.Sites.FirstOrDefault(x=>x.Id==id);if(list.SelectedIndex<0&&list.Items.Count>0)list.SelectedIndex=0;Details();}
    void Details(){var s=Selected;details.Text=s==null?"No sites saved yet. Save the current observing location to get started.":s.Name+"\n\n"+Net.Coord(s.Lat)+", "+Net.Coord(s.Lon)+"\n"+s.Zone+"\n\n"+(s.Sky==null?"Bortle not set":"Bortle "+s.Sky.Bortle.ToString("0.0")+(s.Sky.AreaEstimate?" area estimate":""))+"\nHorizon: "+s.Horizon.Points.Count+" points"+(s.Horizon.Enabled?"":" (off)")+"\nMinimum altitude: "+s.Horizon.MinimumAltitude.ToString("0.#")+"°"+(s.Id==Result.ActiveSiteId?"\n\nCurrently selected site":"");}
    void Add(){using(var edit=new SiteEditorForm(SiteLibrary.Capture(Result)))if(edit.ShowDialog(this)==DialogResult.OK){Result.Sites.Add(edit.Result);SiteLibrary.Use(Result,edit.Result);Reload(edit.Result.Id);}}
    void Edit(){var selected=Selected;if(selected==null)return;using(var edit=new SiteEditorForm(selected))if(edit.ShowDialog(this)==DialogResult.OK){int index=Result.Sites.IndexOf(selected);Result.Sites[index]=edit.Result;if(Result.ActiveSiteId==selected.Id)SiteLibrary.Use(Result,edit.Result);Reload(edit.Result.Id);}}
    void Remove(){var selected=Selected;if(selected==null)return;Result.Sites.Remove(selected);if(Result.ActiveSiteId==selected.Id)Result.ActiveSiteId=null;Reload();}
    void Use(){if(Selected==null)return;SiteLibrary.Use(Result,Selected);DialogResult=DialogResult.OK;Close();}
}
}
